13	pub struct PackageJson {
14	    path: PathBuf,
15	    absolute: PathBuf,
16	    role: ManifestRole,
17	    doc: Map<String, Value>,
18	    fingerprint: FormatFingerprint,
19	    npm_workspace_kind: Option<WorkspaceKind>,
20	}
