242	        .unwrap_or(".changeset");
243	
244	    // Reject any changesets.dir value that is absolute or contains '..'
245	    // components — either would allow load_changesets / atomic_write to
246	    // escape the workspace root. We check components() rather than
247	    // canonicalizing because the directory may not exist yet (e.g. a fresh
248	    // workspace).
249	    let changesets_dir =
250	        callisto_model::workspace_relative(changesets_dir_str).map_err(|_err| {
251	            ConfigError::InvalidChangesetsDir {
252	                dir: changesets_dir_str.to_string(),
253	            }
254	        })?;
255	
256	    let cascade_raw = raw.cascade.unwrap_or_default();
257	    let mode = match cascade_raw.mode.as_deref() {
258	        Some("always") => {
259	            provenance.insert(ConfigKey::CASCADE_MODE, ConfigProvenance::Explicit);
