14	/// Fetches the full, unfiltered list of every tag name in the repository at
15	/// `root`, via [`GitAccess`] (native gix, falling back to a `CommandRunner`-
16	/// shelled `git tag --list` when gix is unavailable -- most notably on
17	/// `wasm32`).
18	///
19	/// Deliberately fetches with no glob pattern (the full tag list): callers
20	/// apply their own glob filtering afterwards via [`matching_tags`], using
21	/// the exact same `globset` matcher both `GitDataSource` backends use
22	/// internally. This guarantees identical tag-selection semantics
23	/// regardless of which backend sourced the raw list, and lets the fetch be
24	/// batched once across every package (see [`TagIndex::build`]) instead of
25	/// once per package -- important on `wasm32`, where each `CommandRunner`
26	/// call is a full Extism guest<->host round-trip.
27	fn fetch_all_tags<R: CommandRunner>(runner: &R, root: &Path) -> Result<Vec<String>, GraphError> {
28	    let git = GitAccess::discover(root, runner);
29	    let tags = git.list_tags(None)?;
30	    Ok(tags.into_iter().map(|t| t.0).collect())
31	}
32	
33	/// Filters `all_tags` down to those matching `template`'s glob.
34	///
35	/// Uses the same `globset::Glob`-based matching
36	/// `callisto_vcs::GitRepository::list_tags` applies internally, kept in
37	/// sync deliberately so tag selection is byte-identical whether `all_tags`
38	/// was sourced via gix or the `CommandRunner` fallback in
39	/// [`fetch_all_tags`]. This includes error behavior: a `template.glob()`
40	/// that fails to compile is surfaced as `Err(GraphError::Vcs(VcsError::
41	/// InvalidGlob))`, matching every tag being the unsafe alternative -- a
42	/// malformed tag template must never silently make "last tag" resolution
43	/// pick an unrelated package's tag.
44	fn matching_tags<'a>(
45	    all_tags: &'a [String],
46	    template: &TagTemplate,
47	) -> Result<Vec<&'a str>, GraphError> {
48	    let glob = template.glob();
49	    let matcher = globset::Glob::new(&glob)
50	        .map(|g| g.compile_matcher())
51	        .map_err(|e| {
52	            GraphError::Vcs(callisto_vcs::VcsError::InvalidGlob {
53	                pattern: glob.clone(),
54	                message: e.to_string(),
55	            })
56	        })?;
57	
58	    Ok(all_tags
59	        .iter()
60	        .filter(|t| matcher.is_match(t.as_str()))
61	        .map(|s| s.as_str())
62	        .collect())
63	}
64	
65	/// Selects the highest-versioned tag matching `template` out of a full tag
66	/// list previously obtained via [`fetch_all_tags`].
67	fn select_from_tags(
68	    all_tags: &[String],
69	    template: &TagTemplate,
70	    grammar: VersionGrammar,
71	) -> Result<LastTagSelection, GraphError> {
72	    let candidates = matching_tags(all_tags, template)?;
73	    select_last_tag(template, grammar, candidates).map_err(GraphError::from)
74	}
75	
76	/// Resolves the last release tag matching a single package's `template`.
77	///
78	/// Kept for API compatibility with existing callers, and safe to use
79	/// standalone. Note that this re-fetches the full tag list (gix discovery
80	/// or a `CommandRunner` round-trip) on every call; callers resolving tags
81	/// for many packages at once -- notably [`TagIndex::build`] -- fetch the
82	/// list once and reuse it across packages rather than calling this
83	/// function in a loop.
84	pub fn last_tag_for<R: CommandRunner>(
85	    runner: &R,
86	    root: &Path,
87	    template: &TagTemplate,
88	    grammar: VersionGrammar,
89	) -> Result<LastTagSelection, GraphError> {
90	    let all_tags = fetch_all_tags(runner, root)?;
91	    select_from_tags(&all_tags, template, grammar)
92	}
