    fn resolve_pre_cursor_shells_expected_rev_parse_args() {
        struct AssertingRunner;
        impl CommandRunner for AssertingRunner {
            fn run(
                &self,
                program: &str,
                args: &[&str],
                _cwd: &Path,
            ) -> Result<CommandOutput, CommandError> {
                assert_eq!(program, "git");
                assert_eq!(
                    args,
                    [
                        "rev-parse",
                        "--verify",
                        "--quiet",
                        "refs/callisto/pre-cursor/my-crate"
                    ]
