        let runner = CannedRunner(Ok(ok(0, "")));
        let id = PackageId::parse("my-crate").unwrap();
        let result = resolve_pre_cursor(&runner, Path::new("."), &id).unwrap();
        assert_eq!(result, None);
    }

    #[test]
